func (this *Indodax) fetchMarketsBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	listEp710 := <-this.PublicGetApiPairs(params)
	if listEp710.Err != nil {
		panic(listEp710.Err)
	}
	var response []any = listEp710.Value
	var increments any = map[string]any{}

	{
		func(this *Indodax) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Indodax) any {
						// catch block:
						increments = map[string]any{}
						return nil
					}(this)
				}
			}()
			// try block:

			r := <-this.PublicGetApiPriceIncrements(map[string]any{})
			if r.Err != nil {
				panic(r.Err)
			}
			var incrementsResponse map[string]any = r.Value
			increments = this.SafeDict(incrementsResponse, "increments", map[string]any{})
			return nil
		}(this)

	}
	//
	//     [
	//         {
	//             "id": "btcidr",
	//             "symbol": "BTCIDR",
	//             "base_currency": "idr",
	//             "traded_currency": "btc",
	//             "traded_currency_unit": "BTC",
	//             "description": "BTC/IDR",
	//             "ticker_id": "btc_idr",
	//             "volume_precision": 0,
	//             "price_precision": 1000,
	//             "price_round": 8,
	//             "pricescale": 1000,
	//             "quantity_increment": "0.00000001",
	//             "trade_min_base_currency": 10000,
	//             "trade_min_traded_currency": 0.00007457,
	//             "has_memo": false,
	//             "memo_name": false,
	//             "has_payment_id": false,
	//             "trade_fee_percent": 0.3,
	//             "trade_fee_percent_maker": 0.1,
	//             "trade_fee_percent_taker": 0.2,
	//             "url_logo": "https://indodax.com/v2/logo/svg/color/btc.svg",
	//             "url_logo_png": "https://indodax.com/v2/logo/png/color/btc.png",
	//             "is_maintenance": 0
	//         }
	//     ]
	//
	var result []any = []any{}
	var rawMarkets []any = this.ToArray(response)
	for i := 0; i < len(rawMarkets); i++ {
		var market any = func() any {
			if i >= 0 && i < len(rawMarkets) {
				return DerefScalar(rawMarkets[i])
			}
			return nil
		}()
		var id *string = this.SafeString(market, "id")
		var baseId *string = this.SafeString(market, "traded_currency")
		var quoteId *string = this.SafeString(market, "base_currency")
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var isMaintenance *int64 = this.SafeInteger(market, "is_maintenance")
		var inMaintenance bool = (isMaintenance != nil) && (isMaintenance == nil || *isMaintenance != 0)
		var active bool = true
		if inMaintenance {
			active = false
		}
		var fee any = this.ParsePublicTradingFee(market)
		var taker any = nil
		var maker any = nil
		if !IsEqual(fee, nil) {
			taker = GetValue(fee, "taker")
			maker = GetValue(fee, "maker")
		}
		var amountStep *string = this.SafeString(market, "quantity_increment", "0.00000001")
		var priceStep any = this.PairIncrement(market, increments)
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         *base + "/" + *quote,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         false,
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         active,
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"taker":          taker,
			"maker":          maker,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"percentage":     true,
			"tierBased":      false,
			"precision": map[string]any{
				"amount": this.ParseNumber(amountStep),
				"price":  this.ParseNumber(this.PairPriceStep(market, priceStep)),
				"cost":   this.ParseNumber(this.ParsePrecision(this.SafeString(market, "volume_precision"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "trade_min_traded_currency"),
					"max": nil,
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.SafeNumber(market, "trade_min_base_currency"),
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- AsyncResult[any]{Value: result}
	return nil
}

