func (this *Indodax) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//     {
	//         "high":"0.01951",
	//         "low":"0.01877",
	//         "vol_eth":"39.38839319",
	//         "vol_btc":"0.75320886",
	//         "last":"0.01896",
	//         "buy":"0.01896",
	//         "sell":"0.019",
	//         "server_time":1565248908
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var symbol *string = this.SafeSymbol(nil, market)
	var timestamp *int64 = this.SafeTimestamp(ticker, "server_time")
	var baseVolume *string = SafeStringPtr(Add("vol_", this.SafeStringLower(market, "baseId")))
	var quoteVolume *string = SafeStringPtr(Add("vol_", this.SafeStringLower(market, "quoteId")))
	var last *string = this.SafeString(ticker, "last")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "buy"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "sell"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, baseVolume),
		"quoteVolume":   this.SafeString(ticker, quoteVolume),
		"info":          ticker,
	}, market)
}

