/**
 * @method
 * @name indodax#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Indodax) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOHLCVBody(ch chan AsyncResult[any], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var selectedTimeframe *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var now int64 = this.Seconds()
	var until *int64 = this.SafeInteger(params, "until", now)
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"until"})
	var request map[string]any = map[string]any{
		"to":     until,
		"tf":     selectedTimeframe,
		"symbol": market["id"],
	}
	var limitResolved any = func() any {
		if limit == nil {
			return 1000
		}
		return limit
	}()
	if since != nil {
		request["from"] = math.Floor(float64(*since) / 1000)
	} else {
		var duration int64 = this.ParseTimeframe(timeframe)
		request["from"] = Subtract(Subtract(now, Multiply(limitResolved, duration)), 1)
	}

	listEp1446 := <-this.PublicGetTradingviewHistoryV2(this.Extend(request, paramsOmitted))
	if listEp1446.Err != nil {
		panic(listEp1446.Err)
	}
	var response []any = listEp1446.Value

	//
	//     [
	//         {
	//             "Time": 1708416900,
	//             "Open": 51707.52,
	//             "High": 51707.52,
	//             "Low": 51707.52,
	//             "Close": 51707.52,
	//             "Volume": "0"
	//         }
	//     ]
	//
	ch <- AsyncResult[any]{Value: this.ParseOHLCVs(this.ToArray(response), market, timeframe, since, limitResolved)}
	return nil
}
func (this *Indodax) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"open":             "open",
		"filled":           "closed",
		"cancelled":        "canceled",
		"NEW":              "open",
		"PARTIALLY_FILLED": "open",
		"FILLED":           "closed",
		"CANCELLED":        "canceled",
		"CANCELED":         "canceled",
		"REJECTED":         "rejected",
		"EXPIRED":          "expired",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Indodax) ParseOrder(order any, optionalArgs ...any) Order {
	// copy so Java and Go accept this return; parseV2Order already built the order
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	if (InOp(order, "origQty")) || (InOp(order, "oriQty")) || (InOp(order, "fullOrderId")) || (InOp(order, "executedQty")) {
		return OrderFromMap(this.Extend(this.ParseV2Order(order, market), map[string]any{}))
	}
	//
	//     {
	//         "order_id": "12345",
	//         "submit_time": "1392228122",
	//         "price": "8000000",
	//         "type": "sell",
	//         "order_ltc": "100000000",
	//         "remain_ltc": "100000000"
	//     }
	//
	// market closed orders - note that the price is very high
	// and does not reflect actual price the order executed at
	//
	//     {
	//       "order_id": "49326856",
	//       "type": "sell",
	//       "price": "1000000000",
	//       "submit_time": "1618314671",
	//       "finish_time": "1618314671",
	//       "status": "filled",
	//       "order_xrp": "30.45000000",
	//       "remain_xrp": "0.00000000"
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "order_id": 666883,
	//        "client_order_id": "clientx-sj82ks82j",
	//        "type": "sell",
	//        "pair": "btc_idr",
	//        "balance": {
	//            "idr": "33605800",
	//            "btc": "0.00000000",
	//            ...
	//            "frozen_idr": "0",
	//            "frozen_btc": "0.00000000",
	//            ...
	//        }
	//    }
	//
	var side *string = nil
	if InOp(order, "type") {
		side = this.SafeString(order, "type")
	}
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status", "open"))
	var symbol any = nil
	var cost *string = nil
	var price *string = this.SafeString(order, "price")
	var amount *string = nil
	var remaining *string = nil
	var filled *string = nil
	var marketId *string = this.SafeString(order, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	if marketResolved != nil {
		symbol = marketResolved["symbol"]
		var quoteId *string = this.SafeString(marketResolved, "quoteId")
		var baseId *string = this.SafeString(marketResolved, "baseId")
		if (quoteId == nil) || (baseId == nil) {
			var resolved map[string]any = MapTyped(this.MarketFromV1Pair(marketId))
			var resolvedQuoteId *string = this.SafeString(resolved, "quoteId")
			var resolvedBaseId *string = this.SafeString(resolved, "baseId")
			if resolvedQuoteId != nil {
				quoteId = resolvedQuoteId
				symbol = DerefScalar(this.SafeString(resolved, "symbol", symbol))
			}
			if resolvedBaseId != nil {
				baseId = resolvedBaseId
			}
		}
		if (quoteId != nil && *quoteId == "idr") && (InOp(order, "order_rp")) {
			quoteId = SafeStringPtr("rp")
		}
		if (baseId != nil && *baseId == "idr") && (InOp(order, "remain_rp")) {
			baseId = SafeStringPtr("rp")
		}
		if quoteId != nil {
			var costKey string = "order_" + *quoteId
			cost = this.SafeString(order, costKey)
		}
		if baseId != nil {
			var amountKey string = "order_" + *baseId
			var remainKey string = "remain_" + *baseId
			var filledKey string = "receive_" + *baseId
			amount = this.SafeString(order, amountKey)
			remaining = this.SafeString(order, remainKey)
			// filled buy orders on idr-quoted markets carry the executed base amount
			// only in a dynamic receive_{base} field, https://github.com/ccxt/ccxt/issues/26413
			filled = this.SafeString(order, filledKey)
		}
	}
	var timestamp *int64 = this.SafeInteger(order, "submit_time")
	var fee any = nil
	var id *string = this.SafeString(order, "order_id")
	return this.SafeOrder(map[string]any{
		"info":               order,
		"id":                 id,
		"clientOrderId":      this.SafeString(order, "client_order_id"),
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               "limit",
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               cost,
		"average":            nil,
		"amount":             amount,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
	})
}

/**
 * @method
 * @name indodax#fetchOrder
 * @description fetches information on an order made by the user
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#get-order-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#get-order
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.clientOrderId] client order id, only used when options.tapiVersion is "2"
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) FetchOrderAsync(id any, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOrderBody(ch chan AsyncResult[map[string]any], id any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbol := GetArg(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.IsTapiV2() {
		if this.Markets == nil {

			r := <-this.LoadMarketsAsync()
			if r.Err != nil {
				panic(r.Err)
			}
		}
		var orderRequest any = this.V2OrderRequest(id, symbol, params)
		var v2Market map[string]any = this.Market(symbol)
		var v2Request any = GetValue(orderRequest, 1)
		var paramsRest any = GetValue(orderRequest, 2)

		r1 := <-this.V2GetOrder(this.Extend(v2Request, paramsRest))
		if r1.Err != nil {
			panic(r1.Err)
		}
		var v2Response map[string]any = r1.Value

		ch <- AsyncResult[map[string]any]{Value: OrderToMap(this.ParseOrder(v2Response, v2Market))}
		return nil
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchOrder() requires a symbol argument"))
	}
	if this.Markets == nil {

		r2 := <-this.LoadMarketsAsync()
		if r2.Err != nil {
			panic(r2.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":     this.V1PairId(market),
		"order_id": id,
	}

	r3 := <-this.PrivatePostGetOrder(this.Extend(request, params))
	if r3.Err != nil {
		panic(r3.Err)
	}
	response := r3.Raw
	var orders map[string]any = SafeMapTyped(response, "return")
	var order map[string]any = OrderToMap(this.ParseOrder(this.Extend(map[string]any{
		"id": id,
	}, orders["order"]), market))
	order["info"] = response

	ch <- AsyncResult[map[string]any]{Value: order}
	return nil
}

/**
 * @method
 * @name indodax#fetchOpenOrders
 * @description fetch all unfilled currently open orders
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#open-orders-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#pending-order
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch open orders for
 * @param {int} [limit] the maximum number of  open orders structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) FetchOpenOrdersAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchOpenOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Indodax) fetchOpenOrdersBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.IsTapiV2() {

		r := <-this.OpenOrdersV2Async(symbol, since, limit, params)
		if r.Err != nil {
			panic(r.Err)
		}
		ch <- AsyncResult[any]{Value: r.Value}
		return nil
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = nil
	var request map[string]any = map[string]any{}
	if symbol != nil {
		market = this.Market(symbol)
		request["pair"] = this.V1PairId(market)
	}

	r2 := <-this.PrivatePostOpenOrders(this.Extend(request, params))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	var openOrdersResult map[string]any = SafeMapTyped(response, "return")
	var rawOrders any = openOrdersResult["orders"]
	// { success: 1, return: { orders: null }} if no orders
	if IsEqual(rawOrders, nil) {

		ch <- AsyncResult[any]{Value: []any{}}
		return nil
	}
	// { success: 1, return: { orders: [ ... objects ] }} for orders fetched by symbol
	if symbol != nil {

		ch <- AsyncResult[any]{Value: this.ParseOrders(rawOrders, market, since, limit)}
		return nil
	}
	// { success: 1, return: { orders: { marketid: [ ... objects ] }}} if all orders are fetched
	var marketIds []string = ObjectKeys(rawOrders)
	var exchangeOrders []any = []any{}
	for i := 0; i < len(marketIds); i++ {
		var marketId string = marketIds[i]
		var marketOrders any = GetValue(rawOrders, marketId)
		var pairMarketId *string = this.SafeString(this.MarketFromV1Pair(marketId), "id", marketId)
		market = this.SafeMarket(pairMarketId, nil, "_")
		var parsedOrders any = this.ParseOrders(marketOrders, market, since, limit)
		exchangeOrders = this.ArrayConcat(exchangeOrders, parsedOrders)
	}

	ch <- AsyncResult[any]{Value: exchangeOrders}
	return nil
}

/**
 * @method
 * @name indodax#fetchClosedOrders
 * @description fetches information on multiple closed orders made by the user
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#order-history
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#order-history
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) FetchClosedOrdersAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchClosedOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Indodax) fetchClosedOrdersBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.IsTapiV2() {

		r := <-this.FetchOrdersAsync(symbol, since, limit, params)
		if r.Err != nil {
			panic(r.Err)
		}
		var closedOrders []any = ListTyped(r.Value)

		ch <- AsyncResult[any]{Value: this.FilterBy(closedOrders, "status", "closed")}
		return nil
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchClosedOrders() requires a symbol argument"))
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair": this.V1PairId(market),
	}

	r2 := <-this.PrivatePostOrderHistory(this.Extend(request, params))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = MapTyped(r2.Raw)
	var historyResult map[string]any = SafeMapTyped(response, "return")
	var orders any = this.ParseOrders(historyResult["orders"], market)
	orders = this.FilterBy(orders, "status", "closed")

	ch <- AsyncResult[any]{Value: this.FilterBySymbolSinceLimit(orders, symbol, since, limit)}
	return nil
}

/**
 * @method
 * @name indodax#createOrder
 * @description create a trade order
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#trade-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#create-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {float} [params.cost] quote amount to spend on a market buy, only used when options.tapiVersion is "2"
 * @param {string} [params.clientOrderId] client order id, only used when options.tapiVersion is "2"
 * @param {string} [params.timeInForce] GTC or MOC, only used when options.tapiVersion is "2"
 * @param {string} [params.selfTradePreventionMode] EXPIRE_TAKER, EXPIRE_MAKER, or EXPIRE_BOTH, only used when options.tapiVersion is "2"
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Indodax) createOrderBody(ch chan AsyncResult[map[string]any], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.IsTapiV2() {
		if this.Markets == nil {

			r := <-this.LoadMarketsAsync()
			if r.Err != nil {
				panic(r.Err)
			}
		}
		var v2Market map[string]any = this.Market(symbol)
		if false {
			panic(ArgumentsRequired(this.Id + " createOrder() requires a side argument"))
		}
		var clientOrderId *string = this.SafeString(params, "clientOrderId")
		var timeInForce *string = this.SafeString(params, "timeInForce")
		var selfTradePreventionMode *string = this.SafeString(params, "selfTradePreventionMode")
		var cost *string = this.SafeString(params, "cost")
		var paramsOmitted map[string]any = this.OmitDict(params, []any{"clientOrderId", "timeInForce", "selfTradePreventionMode", "cost"})
		var v2Request map[string]any = map[string]any{
			"symbol": this.TapiV2Symbol(v2Market),
			"side":   strings.ToUpper(side),
			"type":   strings.ToUpper(typeVar),
		}
		if typeVar == "market" {
			if side == "buy" {
				var quoteAmount any = nil
				if cost != nil {
					quoteAmount = this.CostToPrecision(symbol, cost)
				} else {
					if price == nil {
						panic(InvalidOrder(this.Id + " createOrder() requires the price argument or params.cost for market buy orders"))
					}
					var amountString *string = this.NumberToString(amount)
					var priceString *string = this.NumberToString(price)
					quoteAmount = this.CostToPrecision(symbol, Precise.StringMul(amountString, priceString))
				}
				v2Request["quoteOrderQty"] = quoteAmount
			} else {
				v2Request["quantity"] = this.AmountToPrecision(symbol, amount)
			}
		} else if typeVar == "limit" {
			if price == nil {
				panic(InvalidOrder(this.Id + " createOrder() requires a price argument for a limit order"))
			}
			v2Request["price"] = this.PriceToPrecision(symbol, price)
			v2Request["quantity"] = this.AmountToPrecision(symbol, amount)
			if timeInForce != nil {
				v2Request["timeInForce"] = timeInForce
			}
		} else {
			panic(InvalidOrder(this.Id + " createOrder() does not support order type " + typeVar))
		}
		if clientOrderId != nil {
			v2Request["newClientOrderId"] = clientOrderId
		}
		if selfTradePreventionMode != nil {
			v2Request["selfTradePreventionMode"] = selfTradePreventionMode
		}

		r1 := <-this.V2PostOrder(this.Extend(v2Request, paramsOmitted))
		if r1.Err != nil {
			panic(r1.Err)
		}
		var v2Response map[string]any = r1.Value

		ch <- AsyncResult[map[string]any]{Value: OrderToMap(this.ParseOrder(v2Response, v2Market))}
		return nil
	}
	if this.Markets == nil {

		r2 := <-this.LoadMarketsAsync()
		if r2.Err != nil {
			panic(r2.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"pair":  this.V1PairId(market),
		"type":  side,
		"price": price,
	}
	var priceIsRequired bool = false
	var quantityIsRequired bool = false
	if typeVar == "market" {
		if side == "buy" {
			var quoteAmount any = nil
			var cost *float64 = this.SafeNumber(params, "cost")
			if cost != nil {
				quoteAmount = this.CostToPrecision(symbol, cost)
			} else {
				if price == nil {
					panic(InvalidOrder(this.Id + " createOrder() requires the price argument for market buy orders to calculate the total cost to spend (amount * price)."))
				}
				var amountString *string = this.NumberToString(amount)
				var priceString *string = this.NumberToString(price)
				var costRequest *string = Precise.StringMul(amountString, priceString)
				quoteAmount = this.CostToPrecision(symbol, costRequest)
			}
			AddElementToObject(request, market["quoteId"], quoteAmount)
		} else {
			quantityIsRequired = true
		}
	} else if typeVar == "limit" {
		priceIsRequired = true
		quantityIsRequired = true
		if side == "buy" {
			AddElementToObject(request, market["quoteId"], this.ParseToNumeric(this.CostToPrecision(symbol, Precise.StringMul(this.NumberToString(amount), this.NumberToString(price)))))
		}
	}
	if priceIsRequired {
		if price == nil {
			panic(InvalidOrder(this.Id + " createOrder() requires a price argument for a " + typeVar + " order"))
		}
		request["price"] = price
	}
	if quantityIsRequired {
		AddElementToObject(request, market["baseId"], this.AmountToPrecision(symbol, amount))
	}
	var tradeParams map[string]any = func() map[string]any {
		if (typeVar == "market") && (side == "buy") {
			return this.OmitDict(params, "cost")
		}
		return params
	}()

	r3 := <-this.PrivatePostTrade(this.Extend(request, tradeParams))
	if r3.Err != nil {
		panic(r3.Err)
	}
	result := r3.Raw
	var data map[string]any = SafeMapTyped(result, "return")
	var id *string = this.SafeString(data, "order_id")

	ch <- AsyncResult[map[string]any]{Value: OrderToMap(this.SafeOrder(map[string]any{
		"info": result,
		"id":   id,
	}, market))}
	return nil
}

/**
 * @method
 * @name indodax#cancelOrder
 * @description cancels an open order
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#cancel-order-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#cancel-order
 * @param {string} id order id
 * @param {string} symbol unified symbol of the market the order was made in
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.side] order side, required on TAPI v1 and not used when options.tapiVersion is "2"
 * @param {string} [params.clientOrderId] client order id, only used when options.tapiVersion is "2"
 * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Indodax) CancelOrderAsync(id any, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.cancelOrderBody(ch, id, optionalArgs...)
	return ch
}
func (this *Indodax) cancelOrderBody(ch chan AsyncResult[map[string]any], id any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	symbol := GetArg(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.IsTapiV2() {
		if this.Markets == nil {

			r := <-this.LoadMarketsAsync()
			if r.Err != nil {
				panic(r.Err)
			}
		}
		var orderRequest any = this.V2OrderRequest(id, symbol, params)
		var v2Market map[string]any = this.Market(symbol)
		var v2Request any = GetValue(orderRequest, 1)
		var paramsRest any = GetValue(orderRequest, 2)

		r1 := <-this.V2DeleteOrder(this.Extend(v2Request, paramsRest))
		if r1.Err != nil {
			panic(r1.Err)
		}
		var v2Response map[string]any = r1.Value

		ch <- AsyncResult[map[string]any]{Value: OrderToMap(this.ParseOrder(v2Response, v2Market))}
		return nil
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " cancelOrder() requires a symbol argument"))
	}
	var side *string = this.SafeString(params, "side")
	if side == nil {
		panic(ArgumentsRequired(this.Id + " cancelOrder() requires an extra \"side\" param"))
	}
	if this.Markets == nil {

		r2 := <-this.LoadMarketsAsync()
		if r2.Err != nil {
			panic(r2.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"order_id": id,
		"pair":     this.V1PairId(market),
		"type":     side,
	}

	r3 := <-this.PrivatePostCancelOrder(this.Extend(request, params))
	if r3.Err != nil {
		panic(r3.Err)
	}
	var response map[string]any = r3.Value
	//
	//    {
	//        "success": 1,
	//        "return": {
	//            "order_id": 666883,
	//            "client_order_id": "clientx-sj82ks82j",
	//            "type": "sell",
	//            "pair": "btc_idr",
	//            "balance": {
	//                "idr": "33605800",
	//                "btc": "0.00000000",
	//                ...
	//                "frozen_idr": "0",
	//                "frozen_btc": "0.00000000",
	//                ...
	//            }
	//        }
	//    }
	//
	var data map[string]any = SafeMapTyped(response, "return")

	ch <- AsyncResult[map[string]any]{Value: OrderToMap(this.ParseOrder(data))}
	return nil
}

/**
 * @method
 * @name indodax#cancelAllOrdersAfter
 * @description dead man's switch, cancel all orders after a countdown in milliseconds, and 0 stops the timer
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Deadman-switch.md
 * @param {number} timeout time in milliseconds, 0 represents cancel the timer
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.symbol] unified market symbol
 * @param {string[]} [params.symbols] list of unified market symbols, joined into one pair list
 * @returns {object} the raw api response
 */
func (this *Indodax) CancelAllOrdersAfterAsync(timeout int64, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.cancelAllOrdersAfterBody(ch, timeout, optionalArgs...)
	return ch
}
func (this *Indodax) cancelAllOrdersAfterBody(ch chan AsyncResult[any], timeout int64, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if false {
		panic(ArgumentsRequired(this.Id + " cancelAllOrdersAfter() requires a timeout argument"))
	}
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbol *string = this.SafeString(params, "symbol")
	var symbols []any = SafeListTyped(params, "symbols")
	var pair any = nil
	if symbols != nil {
		var symbolsLength int = len(symbols)
		if symbolsLength < 1 {
			panic(ArgumentsRequired(this.Id + " cancelAllOrdersAfter() requires a symbol or symbols argument in params"))
		}
		var pairIds []any = []any{}
		for i := 0; i < symbolsLength; i++ {
			var marketSymbol any = func() any {
				if i >= 0 && i < len(symbols) {
					return DerefScalar(symbols[i])
				}
				return nil
			}()
			var market map[string]any = this.Market(marketSymbol)
			pairIds = append(pairIds, this.V1PairId(market))
		}
		pair = Join(pairIds, ",")
	} else if symbol != nil {
		var market map[string]any = this.Market(symbol)
		pair = this.V1PairId(market)
	} else {
		panic(ArgumentsRequired(this.Id + " cancelAllOrdersAfter() requires a symbol or symbols argument in params"))
	}
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"symbol", "symbols"})
	var request map[string]any = map[string]any{
		"pair":          pair,
		"countdownTime": timeout,
	}

	r1 := <-this.DeadmanPostCountdownCancelAll(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw

	//
	//     {
	//         "success": 1
	//     }
	//
	ch <- AsyncResult[any]{Value: this.Extend(response, map[string]any{})}
	return nil
}

/**
 * @method
 * @name indodax#fetchTransactionFee
 * @description fetch the fee for a transaction
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#withdraw-fee-endpoints
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [fee structure]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Indodax) FetchTransactionFeeAsync(code string, optionalArgs ...any) <-chan EndpointResult[map[string]any] {
	ch := make(chan EndpointResult[map[string]any], 1)
	go this.fetchTransactionFeeBody(ch, code, optionalArgs...)
	return ch
}
func (this *Indodax) fetchTransactionFeeBody(ch chan EndpointResult[map[string]any], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicErrorT(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.IsTapiV2() {
		panic(NotSupported(this.Id + " fetchTransactionFee() is not available when options.tapiVersion is \"2\""))
	}
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"currency": currency["id"],
	}

	r1 := <-this.PrivatePostWithdrawFee(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     {
	//         "success": 1,
	//         "return": {
	//             "server_time": 1607923272,
	//             "withdraw_fee": 0.005,
	//             "currency": "eth"
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "return")
	var currencyId *string = this.SafeString(data, "currency")

	chValue := map[string]any{
		"info":     response,
		"rate":     this.SafeNumber(data, "withdraw_fee"),
		"currency": this.SafeCurrencyCode(currencyId, currency),
	}
	ch <- EndpointResult[map[string]any]{Value: chValue, Raw: chValue}
	return nil
}

/**
 * @method
 * @name indodax#fetchDepositWithdrawFee
 * @description fetch the withdrawal fee for a currency; indodax charges no crypto deposit fees, see https://github.com/ccxt/ccxt/issues/25800
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#withdraw-fee-endpoints
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [fee structure]{@link https://docs.ccxt.com/?id=fee-structure}
 */
func (this *Indodax) FetchDepositWithdrawFeeAsync(code string, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchDepositWithdrawFeeBody(ch, code, optionalArgs...)
	return ch
}
func (this *Indodax) fetchDepositWithdrawFeeBody(ch chan AsyncResult[any], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.IsTapiV2() {
		panic(NotSupported(this.Id + " fetchDepositWithdrawFee() is not available when options.tapiVersion is \"2\""))
	}

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"currency": currency["id"],
	}

	r1 := <-this.PrivatePostWithdrawFee(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     {
	//         "success": 1,
	//         "return": {
	//             "server_time": 1607923272,
	//             "withdraw_fee": 0.005,
	//             "currency": "eth"
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "return")
	var result any = this.DepositWithdrawFee(response)
	AddElementToObject(GetValue(result, "withdraw"), "fee", this.SafeNumber(data, "withdraw_fee"))
	AddElementToObject(GetValue(result, "withdraw"), "percentage", false)
	AddElementToObject(GetValue(result, "deposit"), "fee", 0)
	AddElementToObject(GetValue(result, "deposit"), "percentage", false)

	ch <- AsyncResult[any]{Value: this.AssignDefaultDepositWithdrawFees(result, currency)}
	return nil
}

/**
 * @method
 * @name indodax#fetchDepositsWithdrawals
 * @description fetch history of deposits and withdrawals
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#transaction-history-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#get-withdraw-coin-information-history
 * @param {string} [code] unified currency code. On TAPI v2, omitting code returns only BTC crypto history plus IDR fiat history, because the exchange defaults coin to BTC
 * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal, default is undefined
 * @param {int} [limit] max number of deposit/withdrawals to return, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a list of [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Indodax) FetchDepositsWithdrawalsAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchDepositsWithdrawalsBody(ch, optionalArgs...)
	return ch
}
func (this *Indodax) fetchDepositsWithdrawalsBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.IsTapiV2() {

		r := <-this.FetchDepositsAsync(code, since, limit, params)
		if r.Err != nil {
			panic(r.Err)
		}
		deposits := r.Value

		r1 := <-this.FetchWithdrawalsAsync(code, since, limit, params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		withdrawals := r1.Value
		var merged []any = this.ArrayConcat(deposits, withdrawals)

		ch <- AsyncResult[any]{Value: this.FilterBySinceLimit(merged, since, limit, "timestamp")}
		return nil
	}
	if this.Markets == nil {

		r2 := <-this.LoadMarketsAsync()
		if r2.Err != nil {
			panic(r2.Err)
		}
	}
	var request map[string]any = map[string]any{}
	if since != nil {
		var startTime string = this.Yyyymmdd(since)
		request["start"] = startTime
		request["end"] = this.Yyyymmdd(this.Milliseconds())
	}

	r3 := <-this.PrivatePostTransHistory(this.Extend(request, params))
	if r3.Err != nil {
		panic(r3.Err)
	}
	var response map[string]any = r3.Value
	//
	//     {
	//         "success": 1,
	//         "return": {
	//             "withdraw": {
	//                 "idr": [
	//                     {
	//                         "status": "success",
	//                         "type": "coupon",
	//                         "rp": "115205",
	//                         "fee": "500",
	//                         "amount": "114705",
	//                         "submit_time": "1539844166",
	//                         "success_time": "1539844189",
	//                         "withdraw_id": "1783717",
	//                         "tx": "BTC-IDR-RDTVVO2P-ETD0EVAW-VTNZGMIR-HTNTUAPI-84ULM9OI",
	//                         "sender": "boris",
	//                         "used_by": "viginia88"
	//                     },
	//                     ...
	//                 ],
	//                 "btc": [],
	//                 "abyss": [],
	//                 ...
	//             },
	//             "deposit": {
	//                 "idr": [
	//                     {
	//                         "status": "success",
	//                         "type": "duitku",
	//                         "rp": "393000",
	//                         "fee": "5895",
	//                         "amount": "387105",
	//                         "submit_time": "1576555012",
	//                         "success_time": "1576555012",
	//                         "deposit_id": "3395438",
	//                         "tx": "Duitku OVO Settlement"
	//                     },
	//                     ...
	//                 ],
	//                 "btc": [
	//                     {
	//                         "status": "success",
	//                         "btc": "0.00118769",
	//                         "amount": "0.00118769",
	//                         "success_time": "1539529208",
	//                         "deposit_id": "3602369",
	//                         "tx": "c816aeb35a5b42f389970325a32aff69bb6b2126784dcda8f23b9dd9570d6573"
	//                     },
	//                     ...
	//                 ],
	//                 "abyss": [],
	//                 ...
	//             }
	//         }
	//     }
	//
	var data map[string]any = SafeMapTyped(response, "return")
	var withdraw map[string]any = SafeMapTyped(data, "withdraw")
	var deposit map[string]any = SafeMapTyped(data, "deposit")
	var transactions []any = []any{}
	var currency map[string]any = nil
	if code == nil {
		var keys []string = nil
		if withdraw != nil {
			keys = make([]string, 0, len(withdraw))
			for objectKey := range withdraw {
				keys = append(keys, objectKey)
			}
		}
		for i := 0; i < len(keys); i++ {
			var key string = GetValue(keys, i).(string)
			transactions = this.ArrayConcat(transactions, withdraw[key])
		}
		keys = ObjectKeys(deposit)
		for i := 0; i < len(keys); i++ {
			var key string = GetValue(keys, i).(string)
			transactions = this.ArrayConcat(transactions, deposit[key])
		}
	} else {
		currency = this.Currency(code)
		var withdraws []any = SafeListTypedDefault(withdraw, GetValue(currency, "id"), []any{})
		var deposits []any = SafeListTypedDefault(deposit, GetValue(currency, "id"), []any{})
		transactions = this.ArrayConcat(withdraws, deposits)
	}

	ch <- AsyncResult[any]{Value: this.ParseTransactions(transactions, currency, since, limit)}
	return nil
}

/**
 * @method
 * @name indodax#withdraw
 * @description make a withdrawal
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#withdraw-coin-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#withdraw-coin
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#withdraw-idr
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.network] unified network code, used for crypto withdrawals when options.tapiVersion is "2"
 * @param {string} [params.clientOrderId] client request id, only used when options.tapiVersion is "2"
 * @param {string} [params.bankCode] bank code for an IDR withdrawal when options.tapiVersion is "2"
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Indodax) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan EndpointResult[map[string]any] {
	ch := make(chan EndpointResult[map[string]any], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Indodax) withdrawBody(ch chan EndpointResult[map[string]any], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicErrorT(ch)
	var tag *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = tag
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.IsTapiV2() {

		r := <-this.SendWithdrawV2Async(code, amount, address, tag, params)
		if r.Err != nil {
			panic(r.Err)
		}
		withdrawal := r.Value

		chValue := this.Extend(withdrawal, map[string]any{})
		ch <- EndpointResult[map[string]any]{Value: chValue, Raw: chValue}
		return nil
	}
	var withdrawTag any = this.HandleWithdrawTagAndParams(tag, params)
	var tagWithdrawTag *string = SafeStringPtr(GetValue(withdrawTag, 0))
	var paramsWithdrawTag any = GetValue(withdrawTag, 1)
	this.CheckAddress(address)
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	// Custom string you need to provide to identify each withdrawal.
	// Will be passed to callback URL (assigned via website to the API key)
	// so your system can identify the request and confirm it.
	// Alphanumeric, max length 255.
	var requestId int64 = this.Milliseconds()
	// Alternatively:
	// let requestId = this.uuid ();
	var request map[string]any = map[string]any{
		"currency":         currency["id"],
		"withdraw_amount":  amount,
		"withdraw_address": address,
		"request_id":       strconv.FormatInt(requestId, 10),
	}
	if (tagWithdrawTag != nil) && (tagWithdrawTag == nil || *tagWithdrawTag != "") {
		request["withdraw_memo"] = tagWithdrawTag
	}

	r2 := <-this.PrivatePostWithdrawCoin(this.Extend(request, paramsWithdrawTag))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value

	//
	//     {
	//         "success": 1,
	//         "status": "approved",
	//         "withdraw_currency": "xrp",
	//         "withdraw_address": "rwWr7KUZ3ZFwzgaDGjKBysADByzxvohQ3C",
	//         "withdraw_amount": "10000.00000000",
	//         "fee": "2.00000000",
	//         "amount_after_fee": "9998.00000000",
	//         "submit_time": "1509469200",
	//         "withdraw_id": "xrp-12345",
	//         "txid": "",
	//         "withdraw_memo": "123123"
	//     }
	//
	chValue := this.ParseTransaction(response, currency)
	ch <- EndpointResult[map[string]any]{Value: chValue, Raw: chValue}
	return nil
}
func (this *Indodax) ParseTransaction(transaction any, optionalArgs ...any) map[string]any {
	// copy so Go accepts this return; parseV2Transaction already built the transaction
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	if (InOp(transaction, "coin")) || (InOp(transaction, "fiatCurrency")) || (InOp(transaction, "withdrawStatus")) || (InOp(transaction, "depositStatus")) || (InOp(transaction, "txType")) {
		return this.Extend(this.ParseV2Transaction(transaction, currency), map[string]any{})
	}
	//
	// withdraw
	//
	//     {
	//         "success": 1,
	//         "status": "approved",
	//         "withdraw_currency": "xrp",
	//         "withdraw_address": "rwWr7KUZ3ZFwzgaDGjKBysADByzxvohQ3C",
	//         "withdraw_amount": "10000.00000000",
	//         "fee": "2.00000000",
	//         "amount_after_fee": "9998.00000000",
	//         "submit_time": "1509469200",
	//         "withdraw_id": "xrp-12345",
	//         "txid": "",
	//         "withdraw_memo": "123123"
	//     }
	//
	// transHistory
	//
	//     {
	//         "status": "success",
	//         "type": "coupon",
	//         "rp": "115205",
	//         "fee": "500",
	//         "amount": "114705",
	//         "submit_time": "1539844166",
	//         "success_time": "1539844189",
	//         "withdraw_id": "1783717",
	//         "tx": "BTC-IDR-RDTVVO2P-ETD0EVAW-VTNZGMIR-HTNTUAPI-84ULM9OI",
	//         "sender": "boris",
	//         "used_by": "viginia88"
	//     }
	//
	//     {
	//         "status": "success",
	//         "btc": "0.00118769",
	//         "amount": "0.00118769",
	//         "success_time": "1539529208",
	//         "deposit_id": "3602369",
	//         "tx": "c816aeb35a5b42f389970325a32aff69bb6b2126784dcda8f23b9dd9570d6573"
	//     },
	var status *string = this.SafeString(transaction, "status")
	var timestamp *int64 = this.SafeTimestamp2(transaction, "success_time", "submit_time")
	var depositId *string = this.SafeString(transaction, "deposit_id")
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	var fee map[string]any = nil
	if feeCost != nil {
		fee = map[string]any{
			"currency": this.SafeCurrencyCode(nil, currency),
			"cost":     feeCost,
			"rate":     nil,
		}
	}
	return map[string]any{
		"id":          this.SafeString2(transaction, "withdraw_id", "deposit_id"),
		"txid":        this.SafeString2(transaction, "txid", "tx"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"addressFrom": nil,
		"address":     this.SafeString(transaction, "withdraw_address"),
		"addressTo":   nil,
		"amount":      this.SafeNumberN(transaction, []any{"amount", "withdraw_amount", "deposit_amount"}),
		"type": func() string {
			if depositId == nil {
				return "withdraw"
			}
			return "deposit"
		}(),
		"currency": this.SafeCurrencyCode(nil, currency),
		"status":   this.ParseTransactionStatus(status),
		"updated":  nil,
		"tagFrom":  nil,
		"tag":      nil,
		"tagTo":    nil,
		"comment":  this.SafeString(transaction, "withdraw_memo"),
		"internal": nil,
		"fee":      fee,
		"info":     transaction,
	}
}
func (this *Indodax) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"success": "ok",
		"pending": "pending",
		"failed":  "failed",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @ignore
 * @method
 * @name indodax#v1DepositNetwork
 * @description parse a getInfo network value, which may be a string, a comma-separated string, a list, or empty
 * @param {object} networks network map from getInfo
 * @param {string} currencyId currency id key
 * @param {string} code unified currency code
 * @returns {string[]} unified network codes, one per network
 */
func (this *Indodax) V1DepositNetwork(networks any, currencyId string, code any) any {
	var networkList []any = SafeListTyped(networks, currencyId)
	var networkIds []any = []any{}
	if networkList != nil {
		for i := 0; i < len(networkList); i++ {
			var networkId *string = this.SafeString(networkList, i)
			if networkId != nil {
				networkIds = append(networkIds, networkId)
			}
		}
	} else {
		var networkId *string = this.SafeString(networks, currencyId)
		if networkId != nil {
			if func() int {
				if networkId == nil {
					return -1
				}
				return strings.Index(*networkId, ",")
			}() >= 0 {
				var parts []string = strings.Split(*networkId, ",")
				for j := 0; j < len(parts); j++ {
					networkIds = append(networkIds, parts[j])
				}
			} else {
				networkIds = append(networkIds, networkId)
			}
		}
	}
	var parsed []any = []any{}
	for i := 0; i < len(networkIds); i++ {
		var networkCode *string = this.NetworkIdToCode(func() any {
			if i >= 0 && i < len(networkIds) {
				return DerefScalar(networkIds[i])
			}
			return nil
		}(), code)
		if networkCode != nil {
			parsed = append(parsed, strings.ToUpper(*networkCode))
		}
	}
	return parsed
}

/**
 * @method
 * @name indodax#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#general-information-on-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#list-deposit-address
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.network] unified network code, only used when options.tapiVersion is "2"
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Indodax) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Indodax) fetchDepositAddressBody(ch chan AsyncResult[any], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.FetchDepositAddressesAsync([]any{code}, params)
	if r.Err != nil {
		panic(r.Err)
	}
	addresses := r.Value
	var rows []any = this.ToArray(addresses)
	for i := 0; i < len(rows); i++ {
		var row any = func() any {
			if i >= 0 && i < len(rows) {
				return DerefScalar(rows[i])
			}
			return nil
		}()
		var rowCode *string = this.SafeString(row, "currency")
		if rowCode != nil && *rowCode == code {

			ch <- AsyncResult[any]{Value: row}
			return nil
		}
	}
	panic(InvalidAddress(this.Id + " fetchDepositAddress() could not find a deposit address for " + code + ", make sure you have created a corresponding deposit address in your wallet on the exchange website"))
}

/**
 * @method
 * @name indodax#fetchDepositAddresses
 * @description fetch deposit addresses for multiple currencies and chain types
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#general-information-on-endpoints
 * @see https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#list-deposit-address
 * @param {string[]} [codes] list of unified currency codes, required when options.tapiVersion is "2"
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.network] unified network code, only used when options.tapiVersion is "2"
 * @returns {object} a list of [address structures]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Indodax) FetchDepositAddressesAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.fetchDepositAddressesBody(ch, optionalArgs...)
	return ch
}
func (this *Indodax) fetchDepositAddressesBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.IsTapiV2() {

		r := <-this.DepositAddressesV2Async(codes, params)
		if r.Err != nil {
			panic(r.Err)
		}
		ch <- AsyncResult[any]{Value: r.Value}
		return nil
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}

	r2 := <-this.PrivatePostGetInfo(params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//    {
	//        success: '1',
	//        return: {
	//            server_time: '1708031570',
	//            balance: {
	//                idr: '29952',
	//                ...
	//            },
	//            balance_hold: {
	//                idr: '0',
	//                ...
	//            },
	//            address: {
	//                btc: '1KMntgzvU7iTSgMBWc11nVuJjAyfW3qJyk',
	//                ...
	//            },
	//            memo_is_required: {
	//                btc: { mainnet: false },
	//                ...
	//            },
	//            network: {
	//                btc: 'mainnet',
	//                ...
	//            },
	//            user_id: '276011',
	//            name: '',
	//            email: 'testbitcoincoid@mailforspam.com',
	//            profile_picture: null,
	//            verification_status: 'unverified',
	//            gauth_enable: true,
	//            withdraw_status: '0'
	//        }
	//    }
	//
	var data map[string]any = SafeMapTyped(response, "return")
	var addresses map[string]any = SafeMapTyped(data, "address")
	var networks map[string]any = this.SafeDictMap(data, "network", map[string]any{})
	var addressKeys []string = nil
	if addresses != nil {
		addressKeys = make([]string, 0, len(addresses))
		for objectKey := range addresses {
			addressKeys = append(addressKeys, objectKey)
		}
	}
	var result []any = []any{}
	for i := 0; i < len(addressKeys); i++ {
		var marketId string = addressKeys[i]
		var code *string = this.SafeCurrencyCode(marketId)
		var address *string = this.SafeString(addresses, marketId)
		if (address != nil) && ((codes == nil) || (this.InArray(code, codes))) {
			this.CheckAddress(address)
			var networkCodes any = this.V1DepositNetwork(networks, marketId, code)
			var networkCount int = GetArrayLength(networkCodes)
			if code != nil {
				if networkCount < 1 {
					result = append(result, map[string]any{
						"info":     map[string]any{},
						"currency": code,
						"network":  nil,
						"address":  address,
						"tag":      nil,
					})
				} else {
					for n := 0; n < networkCount; n++ {
						var networkCode *string = SafeStringPtr(GetValue(networkCodes, n))
						result = append(result, map[string]any{
							"info":     map[string]any{},
							"currency": code,
							"network":  networkCode,
							"address":  address,
							"tag":      nil,
						})
					}
				}
			}
		}
	}

	ch <- AsyncResult[any]{Value: result}
	return nil
}

